-- V36: owner-approved Safari catalog corrections, 2026-10-25.
-- DML stays outside jOOQ DDL simulation, like V17/V25.
-- Forward-only: never rewrites booking, payment, request or cost snapshots.
-- Unknown prices/content drift are refused rather than silently overwriting edits.
-- Source: clients/safari-tours-sharm/marketing/owner-corrections/2026-10-25_catalog-revision.json
DO $revision$
BEGIN
